CREATE TABLE organization_units (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), kind TEXT NOT NULL CHECK(kind IN ('department','team','office','room')), parent_id TEXT, name TEXT NOT NULL, manager_id TEXT, status TEXT NOT NULL, data_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,parent_id) REFERENCES organization_units(company_id,id));
CREATE INDEX organization_units_kind ON organization_units(company_id,kind,status);
CREATE TABLE strategy_items (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), kind TEXT NOT NULL CHECK(kind IN ('objective','initiative','project','goal','milestone')), parent_id TEXT, name TEXT NOT NULL, owner_id TEXT NOT NULL, manager_id TEXT NOT NULL, status TEXT NOT NULL, requirements_json TEXT NOT NULL, constraints_json TEXT NOT NULL, success_measures_json TEXT NOT NULL, dependencies_json TEXT NOT NULL, risks_json TEXT NOT NULL, evidence_json TEXT NOT NULL, target_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,parent_id) REFERENCES strategy_items(company_id,id));
CREATE INDEX strategy_items_kind ON strategy_items(company_id,kind,status,updated_at DESC);
